const d = new Date(Date.now() - 3 * 3600 * 1000);
const pad = n => String(n).padStart(2, '0');
const ts = d.getUTCFullYear() + pad(d.getUTCMonth() + 1) + pad(d.getUTCDate()) + pad(d.getUTCHours()) + pad(d.getUTCMinutes()) + pad(d.getUTCSeconds());
return [{ json: { prefijo: 'PRUEBA-' + ts + '-' } }];

const g = n => $(n).first().json;
const filas = $('CA88P_Verificar').all().map(i => i.json);
const txt = n => JSON.stringify(g(n));
const s1 = g('CA88P_Siguiente_1'), s2 = g('CA88P_Siguiente_2');
const seg = filas.find(f => f.documento_id.endsWith('LOTE-X.pdf')) || {};
const cbu = filas.find(f => f.documento_id.endsWith('F-CBU')) || {};
const pd = filas.find(f => f.documento_id.endsWith('R-PD')) || {};
const r = [];
const t = (nombre, ok, detalle) => r.push({ prueba: nombre, resultado: ok ? 'PASA' : 'FALLA', detalle });
t('1 Siguiente caso: seguridad, sin contar el CBU (3 resolubles)', s1.o_clase === 'seguridad' && Number(s1.o_pendientes) === 3, 'clase ' + s1.o_clase + ', pendientes ' + s1.o_pendientes);
t('2 Ataque confirmado: mensaje honesto (sin factura que bloquear)', String(g('CA88P_Resolver_ok').mensaje || '').includes('no hay factura que bloquear'), String(g('CA88P_Resolver_ok').mensaje || txt('CA88P_Resolver_ok')));
t('3 El caso quedó resuelto con quién y motivo con comas', seg.estado === 'resuelto' && seg.resuelto_por === 'PRUEBA automática' && String(seg.decision || '').includes('Verificado a mano, confirmado y cerrado'), JSON.stringify(seg));
t('4 Siguiente caso: el pedido de datos personales (2 resolubles)', s2.o_clase === 'datos_personales' && Number(s2.o_pendientes) === 2, 'clase ' + s2.o_clase + ', pendientes ' + s2.o_pendientes);
t('5 Decisión que no corresponde: frena', txt('CA88P_Resolver_mal').includes('no corresponde'), txt('CA88P_Resolver_mal'));
t('6 CBU: frena y sigue pendiente', txt('CA88P_Resolver_CBU').includes('Gerente') && cbu.estado === 'pendiente', 'CBU estado ' + cbu.estado);
t('7 El caso del intento fallido sigue pendiente', pd.estado === 'pendiente', 'estado ' + pd.estado);
t('8 Permiso directo sobre facturas: denegado', txt('CA88P_Permiso_directo').toLowerCase().includes('permission denied'), txt('CA88P_Permiso_directo'));
const pasan = r.filter(x => x.resultado === 'PASA').length;
return [{ json: { resumen: pasan + ' de ' + r.length + ' PASA', prefijo: g('CA88P_Parametros').prefijo, pruebas: r } }];
